namespace ghidra.app.util.headless;





using ghidra;
using ghidra;
using ghidra.framework;
using ghidra.framework;
using ghidra.framework.client;
using ghidra.framework.protocol.ghidra;
using ghidra.util;

/**
 * {@link UpdateServerAllowList} utility for managing the Server Allow List.
 * See {@link UrlAllowListManager}.
 */
public class UpdateServerAllowList : GhidraLaunchable {

	private static readonly string INVOCATION_NAME_PROPERTY = "UpdateServerAllowList.Name";

	public UpdateServerAllowList() {
		// Required for GhidraLaunchable
	}

	private URL parseURL(string urlString)
    {
		URI uri = URI.create(urlString);
		return uri.toURL();
	}

	private void checkMoreArgs(int currentArgIndex, string[] args) {
		if (currentArgIndex == args.length - 1) {
			usage(args);
		}
	}

	/* @Override */
	public void launch(GhidraApplicationLayout layout, string[] args)
    {
		Application.initializeApplication(layout, new ApplicationConfiguration());
		if (args.length == 0) {
			usage(args);
		}

		// NOTE: May need other protocol handlers to be registered to avoid URL exceptions
		Handler.registerHandler();

		try {
			bool printList = false;
			for (int i = 0; i < args.length; i++) {
				string arg = args[i];
				switch (arg) {

					case "-allow":
						checkMoreArgs(i, args);
						URL url = parseURL(args[++i]);
						UrlAllowListManager.updateAccess(url, true);
						break;

					case "-disallow":
						checkMoreArgs(i, args);
						url = parseURL(args[++i]);
						UrlAllowListManager.updateAccess(url, false);
						break;

					case "-clear":
						checkMoreArgs(i, args);
						url = parseURL(args[++i]);
						UrlAllowListManager.clearAccessEntry(url);
						break;

					case "-clearAll":
						UrlAllowListManager.clearAll();
						break;

					case "-list":
						printList = true;
						break;

					default:
						usage(args);
				}
			}

			if (printList) {
				Map<ServerSpecification, AccessRecord> accessMap =
					UrlAllowListManager.getAccessMap();
				List<ServerSpecification> servers = new(accessMap.keySet());
				if (servers.isEmpty()) {
					// Do not use logging here as this is a launchable
					Console.WriteLine("Server Allow List is empty.");
				}
				else {
					Collections.sort(servers);
					Console.WriteLine("Server Allow List:");
					foreach (ServerSpecification svr in servers) {

						AccessRecord accessRecord = accessMap.get(svr);
						string access = accessRecord.accessAllowed() ? "ALLOW   " : "DISALLOW";
						Date date = new Date(accessRecord.time());

						Console.WriteLine(
							"   " + access + " " + svr.toUrlString() + " (" + date + ")");
					}
				}
			}
		}
		catch (Exception e) {
			Msg.error("Exception processing Allow List updates", e);
		}
	}

	private static void usage(string[] args) {
		for (int i = 0; i < args.length; i++) {
			Console.Error.WriteLine("arg " + i + ": " + args[i]);
		}
		string invocationName = System.getProperty(INVOCATION_NAME_PROPERTY);

		StringBuffer buf = new StringBuffer();
		buf.append("\nUsage: ");
		buf.append(
			invocationName != null ? invocationName : typeof(UpdateServerAllowList).getSimpleName());
		buf.append(
			" [-allow <protocol>://<hostname>:<port>] [-disallow <protocol>://<hostname>:<port>] [-clear <protocol>://<hostname>:<port>] [-clearAll] [-list]\n");
		Console.Error.WriteLine(buf.toString());
		Environment.Exit(0);
	}
}
